DO $$ DECLARE definition text; BEGIN definition:=pg_get_functiondef('public.checkin_blocker(uuid)'::regprocedure); definition:=replace(definition,$old$WHEN r.status<>'going' THEN 'registration_required'$old$,$new$WHEN r.status<>'going' THEN 'registration_required' WHEN (coalesce(e.price_cents,0)>0 OR EXISTS(SELECT 1 FROM jsonb_array_elements(e.ticket_tiers) t WHERE t->>'id'=r.tier_id AND coalesce((t->>'price_cents')::int,0)>0)) AND NOT EXISTS(SELECT 1 FROM payments p WHERE p.rsvp_id=r.id AND p.event_id=e.id AND p.status='paid' AND p.stripe_payment_intent IS NOT NULL) THEN 'payment_required'$new$); EXECUTE definition; END $$;